//! **RFC-0016's rooted rows** — kernel-route aux tables 132–135 (131 is RFC-0017's eligibility table): journaled `KernelRouteRow`
//! deltas, in the state root, carried and restored like every other aux row; written only past the RFC-0016 fences, which require
//! the kernel route at or below them. The native resource scanner has an explicit arm for each key shape
//! (`palw_native_resource_v1::wire_kernel_aux`, generated by `scripts/drills/gen_rfc06_native_wire.py`); a shape not listed here
//! fails closed.
//!
//! | table | key | value |
//! |---|---|---|
//! | 132 rights reissue snapshot | `epoch (u64 LE) ‖ model (64)` (72 B) | `(allowance u64, reissued u64)` |
//! | 133 pending Final queue | `class (64) ‖ queued_daa (u64 BE) ‖ claim (64)` (136 B) | `(bond PalwBondKeyV2, queued_daa u64, reserved_rights u64)` |
//! | 134 queue membership | `claim (64)` | `(class Hash64, queued_daa u64)` |
//! | 135 telemetry | `0x01 ‖ epoch` (9 B) | `(heartbeat_dependent_daa u64, last_tick_daa u64)` |
//! | | `0x02 ‖ epoch ‖ model` (73 B) | `escrow_paid_sompi u64` |
//! | | `0x03 ‖ kernel claim (64)` (65 B) | `model Hash64` |
//! | | `0x04 ‖ epoch ‖ model` (73 B) | `(dequeued u64, wait_sum_daa u64, wait_max_daa u64)` |

use crate::Hash64;

pub const PALW_RFC0016_RIGHTS_TABLE_V1: u8 = 132;
pub const PALW_RFC0016_QUEUE_TABLE_V1: u8 = 133;
pub const PALW_RFC0016_QUEUE_INDEX_TABLE_V1: u8 = 134;
pub const PALW_RFC0016_TELEMETRY_TABLE_V1: u8 = 135;

pub const PALW_RFC0016_TELEMETRY_HEARTBEAT_PREFIX_V1: u8 = 0x01;
pub const PALW_RFC0016_TELEMETRY_ESCROW_PREFIX_V1: u8 = 0x02;
pub const PALW_RFC0016_TELEMETRY_CLAIM_MODEL_PREFIX_V1: u8 = 0x03;
pub const PALW_RFC0016_TELEMETRY_QUEUE_WAIT_PREFIX_V1: u8 = 0x04;

/// The snapshot's "taken" marker model (no real model id is all zero bytes).
pub const PALW_RFC0016_SNAPSHOT_MARKER_V1: Hash64 = Hash64::from_bytes([0u8; 64]);

pub fn rights_key_v1(epoch: u64, model: &Hash64) -> Vec<u8> {
    let mut k = Vec::with_capacity(72);
    k.extend_from_slice(&epoch.to_le_bytes());
    k.extend_from_slice(model.as_byte_slice());
    k
}

pub fn rights_epoch_prefix_v1(epoch: u64) -> Vec<u8> {
    epoch.to_le_bytes().to_vec()
}

pub fn queue_key_v1(class: &Hash64, queued_daa: u64, claim: &Hash64) -> Vec<u8> {
    let mut k = Vec::with_capacity(136);
    k.extend_from_slice(class.as_byte_slice());
    k.extend_from_slice(&queued_daa.to_be_bytes());
    k.extend_from_slice(claim.as_byte_slice());
    k
}

pub fn queue_class_prefix_v1(class: &Hash64) -> Vec<u8> {
    class.as_byte_slice().to_vec()
}

pub fn queue_index_key_v1(claim: &Hash64) -> Vec<u8> {
    claim.as_byte_slice().to_vec()
}

pub fn telemetry_heartbeat_key_v1(epoch: u64) -> Vec<u8> {
    let mut k = vec![PALW_RFC0016_TELEMETRY_HEARTBEAT_PREFIX_V1];
    k.extend_from_slice(&epoch.to_le_bytes());
    k
}

pub fn telemetry_model_key_v1(prefix: u8, epoch: u64, model: &Hash64) -> Vec<u8> {
    let mut k = vec![prefix];
    k.extend_from_slice(&epoch.to_le_bytes());
    k.extend_from_slice(model.as_byte_slice());
    k
}

pub fn telemetry_claim_model_key_v1(kernel_claim: &[u8; 64]) -> Vec<u8> {
    let mut k = vec![PALW_RFC0016_TELEMETRY_CLAIM_MODEL_PREFIX_V1];
    k.extend_from_slice(kernel_claim);
    k
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn key_shapes_match_the_scanner_arms() {
        let m = Hash64::from_u64_word(7);
        assert_eq!(rights_key_v1(3, &m).len(), 72);
        assert_eq!(queue_key_v1(&m, 9, &m).len(), 136);
        assert_eq!(queue_index_key_v1(&m).len(), 64);
        assert_eq!(telemetry_heartbeat_key_v1(3).len(), 9);
        assert_eq!(telemetry_model_key_v1(PALW_RFC0016_TELEMETRY_ESCROW_PREFIX_V1, 3, &m).len(), 73);
        assert_eq!(telemetry_claim_model_key_v1(&[1u8; 64]).len(), 65);
        // FIFO: the queue key orders by class, then by queued DAA (big-endian), then by claim.
        assert!(queue_key_v1(&m, 9, &m) < queue_key_v1(&m, 10, &Hash64::from_u64_word(1)));
    }
}
